5:     @objc static func analyze(machOContext: OpaquePointer) -> ImportExportAnalysis? {
6:         let ctx = UnsafeMutablePointer<MachOContext>(machOContext)
7:         
8:         
9:         guard let importListPtr = dyld_parse_imports(ctx) else {
10: 
11:             return nil
12:         }
13:         defer { dyld_free_imports(importListPtr) }
14:         
15:         let importList = importListPtr.pointee
16:         var imports: [ImportedSymbol] = []
17:         
18:         if importList.import_count > 0, let importsPtr = importList.imports {
19:             let importsBuffer = UnsafeBufferPointer<ImportInfo>(start: importsPtr, count: Int(importList.import_count))
20:             for importInfo in importsBuffer {
21:                 if let symbol = convertImport(importInfo) {
22:                     imports.append(symbol)
23:                 }
24:             }
25:         }
26:         
27:         // Also parse chained fixups for modern binaries (iOS 15+)
28:         if ctx.pointee.has_chained_fixups {
29:             if let chainedResult = chained_fixups_parse(ctx) {
30:                 let result = chainedResult.pointee
31:                 if result.fixup_count > 0, let fixups = result.fixups {
32:                     for i in 0..<Int(result.fixup_count) {
33:                         let fixup = fixups[i]
34:                         if fixup.is_bind {
35:                             let name = withUnsafePointer(to: fixup.symbol_name) {
36:                                 $0.withMemoryRebound(to: CChar.self, capacity: 256) { String(cString: $0) }
37:                             }
38:                             if !name.isEmpty {
39:                                 let symbol = ImportedSymbol(
40:                                     name: name,
41:                                     libraryName: "",
42:                                     libraryOrdinal: Int(fixup.lib_ordinal),
43:                                     address: fixup.address,
44:                                     bindType: .pointer,
45:                                     isWeak: fixup.is_weak,
46:                                     addend: fixup.addend
47:                                 )
48:                                 // Only add if not already present from dyld_info parsing
49:                                 if !imports.contains(where: { $0.name == name && $0.address == fixup.address }) {
50:                                     imports.append(symbol)
51:                                 }
52:                             }
53:                         }
54:                     }
55:                 }
56:                 chained_fixups_free(chainedResult)
57:             }
58:         }
59: 
