83:         
84:         let libraryList = libraryListPtr.pointee
85:         var libraries: [String] = []
86:         
87:         if libraryList.library_count > 0, let libraryNamesPtr = libraryList.library_names {
88:             for i in 0..<Int(libraryList.library_count) {
