129:     // MARK: - Conversion Helpers
130:     
131:     private static func convertImport(_ importInfo: ImportInfo) -> ImportedSymbol? {
132:         var infoCopy = importInfo
133:         
134:         let name = withUnsafePointer(to: &infoCopy.name.0) { String(cString: $0) }
135:         let libraryName = withUnsafePointer(to: &infoCopy.library_name.0) { String(cString: $0) }
136:         
137:         let bindType: BindType
138:         switch infoCopy.bind_type {
139:         case 1: bindType = .pointer
140:         case 2: bindType = .textAbsolute32
141:         case 3: bindType = .textPCrel32
142:         default: bindType = .pointer
143:         }
144:         
145:         return ImportedSymbol(
146:             name: name,
147:             libraryName: libraryName,
148:             libraryOrdinal: Int(infoCopy.library_ordinal),
149:             address: infoCopy.address,
150:             bindType: bindType,
151:             isWeak: infoCopy.is_weak,
152:             addend: infoCopy.addend
153:         )
154:     }
155:     
156:     private static func convertExport(_ exportInfo: ExportInfo) -> ExportedSymbol? {
157:         var infoCopy = exportInfo
158:         
159:         let name = withUnsafePointer(to: &infoCopy.name.0) { String(cString: $0) }
160:         let reexportLib = withUnsafePointer(to: &infoCopy.reexport_lib.0) { String(cString: $0) }
161:         let reexportName = withUnsafePointer(to: &infoCopy.reexport_name.0) { String(cString: $0) }
162:         
163:         return ExportedSymbol(
164:             name: name,
165:             address: infoCopy.address,
166:             flags: infoCopy.flags,
167:             isReexport: infoCopy.is_reexport,
168:             reexportLibraryName: reexportLib,
169:             reexportSymbolName: reexportName,
170:             isWeakDef: infoCopy.is_weak_def,
171:             isThreadLocal: infoCopy.is_thread_local
172:         )
173:     }
174: }
